import{_ as t,o as a,c as i,a2 as s}from"./chunks/framework.D1JEzK2q.js";const g=JSON.parse('{"title":"WeChat","description":"","frontmatter":{},"headers":[],"relativePath":"channels/wechat.md","filePath":"channels/wechat.md"}'),n={name:"channels/wechat.md"};function o(r,e,l,h,d,p){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="wechat" tabindex="-1">WeChat <a class="header-anchor" href="#wechat" aria-label="Permalink to &quot;WeChat&quot;">​</a></h1><p>WeChat links one personal account per agent using Tencent&#39;s iLink Bot API bridge. Incoming messages arrive through long polling. The gateway integration supports DMs and text replies.</p><h2 id="prerequisites-and-credential-model" tabindex="-1">Prerequisites and credential model <a class="header-anchor" href="#prerequisites-and-credential-model" aria-label="Permalink to &quot;Prerequisites and credential model&quot;">​</a></h2><p>You need a personal WeChat account that can complete the iLink QR authorization flow and an existing gateway agent. Tencent&#39;s <a href="https://github.com/Tencent/openclaw-weixin" target="_blank" rel="noreferrer">openclaw-weixin project</a> is the upstream bridge reference; availability and account eligibility depend on that service.</p><p>There is no API-key field to copy from a developer console. QR authorization creates the session credentials. There is no text device-pairing option and no <code>/webhooks/wechat/...</code> route to publish. Outbound access from the gateway to the iLink service is required.</p><h2 id="configure-and-link" tabindex="-1">Configure and link <a class="header-anchor" href="#configure-and-link" aria-label="Permalink to &quot;Configure and link&quot;">​</a></h2><p>Add the policy fragment to the existing agent entry if managing configuration manually:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;wechat&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;dmPolicy&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;allowlist&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;dmAllowlist&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;pairing&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Optional <code>botAgent</code> is a short sanitized client identity string sent with iLink requests; it does not authenticate the account. Restart after manual edits.</p><p>Open the agent&#39;s WeChat connection settings, start linking, scan the displayed QR with the intended WeChat account, and confirm the authorization. Wait for status <code>linked</code>.</p><p>For API administration, start linking with a gateway key that has write access:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:10850/api/v1/agents/assistant/wechat/link</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;X-Api-Key: YOUR_WRITE_KEY&#39;</span></span></code></pre></div><p>While that request is waiting, query from another terminal:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:10850/api/v1/agents/assistant/wechat/status</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;X-Api-Key: YOUR_WRITE_KEY&#39;</span></span></code></pre></div><p>The status response supplies a QR data URI while <code>pending_scan</code>. Link waits until authorization completes or the approximately two-minute attempt window expires. Possible states are <code>unlinked</code>, <code>pending_scan</code>, <code>linked</code> and <code>reconnecting</code>. The gateway persists the linked session under <code>&lt;workspace&gt;/.wechat-state/</code>; retain that state across restarts.</p><h2 id="approve-a-sender" tabindex="-1">Approve a sender <a class="header-anchor" href="#approve-a-sender" aria-label="Permalink to &quot;Approve a sender&quot;">​</a></h2><p>Send a new private message from a contact. Under the default allowlist policy, the contact gets a pairing code. Compare it with the pending entry in the agent&#39;s WeChat settings, then add the exact iLink sender ID to <code>dmAllowlist</code>. Send another message and verify a reply.</p><p>Administrators can read <code>GET /api/v1/agents/assistant/wechat/pending</code>, then PATCH <code>wechat_dm_allowlist</code> on the agent. Include current approved IDs when replacing the list. Other policy API fields are <code>wechat_dm_policy</code> and <code>wechat_pairing</code>. A WeChat display name, phone number or QR image does not substitute for the sender ID supplied by iLink. The CLI <code>channels approve</code> command is only for Telegram/Discord.</p><p>Linking authorizes the account connection; approving a sender authorizes that person to reach the agent. These are separate checks.</p><h2 id="behavior-and-limitations" tabindex="-1">Behavior and limitations <a class="header-anchor" href="#behavior-and-limitations" aria-label="Permalink to &quot;Behavior and limitations&quot;">​</a></h2><p>This adapter has one account per agent and no group policy fields. It does not provide WeChat group support. iLink polls with a 35-second timeout; an idle long poll is normal. Outgoing text is split around the 4,000-character message cap, preferably on line boundaries.</p><p>Gateway <a href="/claude-gateway/guide/orchestration.html">orchestration</a> applies to WeChat conversations, but this adapter does not implement the voice-note ingestion or native voice controls available on Telegram, Discord, LINE and Slack. Use supported text messages for the first end-to-end test.</p><p>Setting <code>WECHAT_CHANNEL_DISABLED=true</code> in the gateway environment prevents linking and stops previous sessions from resuming on startup. To intentionally remove the account, POST <code>/api/v1/agents/assistant/wechat/unlink</code>; it wipes the linked session and requires a fresh QR authorization.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Check</th></tr></thead><tbody><tr><td>Link returns an error immediately</td><td><code>WECHAT_CHANNEL_DISABLED</code>, service reachability and gateway logs</td></tr><tr><td>QR expires</td><td>Start a new attempt and finish the authorization promptly</td></tr><tr><td>QR scan cannot authorize</td><td>Account eligibility/current iLink availability; use Tencent&#39;s upstream guidance</td></tr><tr><td><code>linked</code> but no answer</td><td>New DM delivered, exact sender ID approved, agent able to execute</td></tr><tr><td>Group messages absent</td><td>Groups are unsupported by this integration</td></tr><tr><td>Repeated relinking after restart</td><td>Persistent, writable <code>.wechat-state</code> directory</td></tr><tr><td>Slow response while idle</td><td>Distinguish normal long-poll wait from processing/network errors</td></tr></tbody></table><p>Implementation references: <a href="https://github.com/0xMaxMa/claude-gateway/blob/b917843/src/wechat/manager.ts" target="_blank" rel="noreferrer">WeChat manager</a>, <a href="https://github.com/0xMaxMa/claude-gateway/blob/b917843/src/wechat/ilink-client.ts" target="_blank" rel="noreferrer">iLink client</a>, and <a href="https://github.com/0xMaxMa/claude-gateway/blob/b917843/src/api/wechat-access.ts" target="_blank" rel="noreferrer">access gate</a>.</p>`,26)])])}const u=t(n,[["render",o]]);export{g as __pageData,u as default};
